// 同一字段序用于原 binary、JSON 与 shape；没有从字段存在推断版本。
#pragma once
#include "care_arrangement.hpp"
#include "care_requirement_codec_fields.hpp"
#include "resident/domains/actor_foundation/condition_head_codec_fields.hpp"
namespace hanmo::resident::care_arrangement_codec {
template<class C>Status moment_refs(C& c,const char* name,std::vector<MomentOwnerSource>& refs){return c.sequence(name,refs,[](auto& x,auto& v){return care_requirement_codec::moment_source(x,v);});}
template<class C>Status terms(C& c,CareArrangementTerms& v){c.field("handover_half_days",v.handover_half_days);c.field("from_tick",v.from_tick);c.optional("until_tick",v.until_tick,[](auto& x,auto& tick){return x.field("value",tick);});c.sequence("allowed_place_ids",v.allowed_place_ids,[](auto& x,auto& id){return care_requirement_codec::text(x,"value",id);});moment_refs(c,"allowed_dependency_refs",v.allowed_dependency_refs);moment_refs(c,"provision_arrangement_refs",v.provision_arrangement_refs);moment_refs(c,"fee_arrangement_refs",v.fee_arrangement_refs);moment_refs(c,"guardianship_permission_refs",v.guardianship_permission_refs);if(!c.status().ok)return c.status();auto valid=validate_care_arrangement_terms_shape(v);return valid.ok?c.status():c.reject(valid.error.original.code);}
template<class C>Status provider(C& c,CareProviderIdentity& v){c.object("provider",[&](auto& x){Integer tag=static_cast<Integer>(v.provider.kind);x.field("kind",tag);if(!x.status().ok)return x.status();if(tag<0||tag>1)return x.reject("CareNamedProviderRequired");if(x.reading())v.provider.kind=static_cast<SubjectKind>(tag);return care_requirement_codec::text(x,"id",v.provider.id);});care_requirement_codec::text(c,"carer_actor_id",v.carer_actor_id);c.optional("institutional_assignment_ref",v.institutional_assignment_ref,[](auto& x,auto& r){return care_requirement_codec::moment_source(x,r);});if(!c.status().ok)return c.status();if(v.provider.kind==SubjectKind::actor&&(v.provider.id!=v.carer_actor_id||v.institutional_assignment_ref))return c.reject("CareActorProviderMismatch");if(v.provider.kind==SubjectKind::organization&&!v.institutional_assignment_ref)return c.reject("CareInstitutionalAssignmentRequired");return c.status();}
template<class C>Status accepted(C& c,AcceptedCaregiver& v,Integer version){if(version<3||version>6)return c.reject("CareExactAcceptanceProfileRequired");care_requirement_codec::text(c,"accepted_id",v.accepted_id);care_requirement_codec::text(c,"requirement_id",v.requirement_id);care_requirement_codec::text(c,"subject_actor_id",v.subject_actor_id);c.object("provider",[&](auto& x){return provider(x,v.provider);});c.object("requirement_transition_ref",[&](auto& x){return care_requirement_codec::source(x,v.requirement_transition_ref);});c.object("terms",[&](auto& x){return terms(x,v.terms);});c.object("accepted_at",[&](auto& x){return family_life4_codec::moment(x,v.accepted_at);});c.object("acceptance_condition_head",[&](auto& x){return actor_condition_codec::head(x,v.acceptance_condition_head);});if(!c.status().ok)return c.status();if(v.acceptance_condition_head.actor_id!=v.provider.carer_actor_id||v.acceptance_condition_head.condition_revision<0||v.subject_actor_id==v.provider.carer_actor_id||v.requirement_transition_ref.domain!="care_requirements"||v.requirement_transition_ref.kind!="care_requirement_changed")return c.reject("InvalidCareAcceptance");return c.status();}
}
